// ─── plugins/native/buttons.js ───
// single_select + CTA button surfaces (todo 18).
//   .اختر / .ازرار / .buttons
//
// One native message carrying:
//   • single_select : live plugin registry (sections = categories, rows = plugins)
//   • cta_url       : the bot's own repository URL (client.config.info.urls.repo)
//   • cta_copy      : a copyable text generated by the bot itself
//   • cta_call      : only when the operator configured a support number
//
// WhatsApp NFM parameter names are used exactly (display_text/id,
// display_title/sections/rows, url, copy_code, phone_number).

import {
  collectCategories,
  infoOf,
  resolvePrefix,
  resolveImages,
  mediaFor,
  say,
  nonEmpty
} from './_native.js';

const MAX_ROWS_PER_SECTION = 10;
const MAX_SECTIONS = 10;

const ALLOWED_NAMES = new Set([
  'quick_reply',
  'cta_url',
  'cta_call',
  'cta_copy',
  'single_select',
  'call_permission_request'
]);

function supportNumber(info) {
  const raw = info?.supportNumber ?? info?.supportPhone ?? info?.support ?? '';
  const digits = String(raw ?? '').replace(/[^\d+]/g, '');
  return digits || null;
}

const handler = async (m, ctx = {}) => {
  try {
    const { conn, bot } = ctx;
    if (!conn?.sendButtonNormal) return say(m, '❌ خدمة الأزرار التفاعلية غير متاحة في هذا الاتصال.');

    const info = infoOf(ctx);
    const prefix = resolvePrefix(ctx, info);
    const images = resolveImages(info);
    const repo = nonEmpty(info?.urls?.repo, '');
    const name = nonEmpty(info?.nameBot, 'البوت');

    if (!/^https?:\/\//i.test(repo)) {
      return say(m, '❌ لم يتم ضبط مستودع البوت في الإعدادات (config.info.urls.repo).');
    }

    const cats = await collectCategories(bot);
    if (!cats.length) {
      return say(m, '❌ لا توجد أوامر لعرضها في قائمة الاختيار.');
    }

    const sections = cats.slice(0, MAX_SECTIONS).map((c) => ({
      title: `${c.emoji} ${c.label}`,
      highlight_label: 'الأوامر',
      rows: c.commands.slice(0, MAX_ROWS_PER_SECTION).map((u) => ({
        title: u,
        description: `أمر من قسم ${c.label}`,
        id: u.startsWith(prefix) ? u : prefix + u
      }))
    })).filter((s) => s.rows.length);

    const buttons = [
      {
        name: 'single_select',
        params: {
          display_title: '📜 اختر أمراً',
          sections
        }
      },
      {
        name: 'cta_url',
        params: { display_text: '📦 مستودع البوت', url: repo }
      },
      {
        name: 'cta_copy',
        params: { display_text: '📋 نسخ بيانات البوت', copy_code: `${name}\n${repo}` }
      }
    ];

    const phone = supportNumber(info);
    if (phone) {
      buttons.push({ name: 'cta_call', params: { display_text: '📞 الدعم', phone_number: phone } });
    }

    // Defensive: the framework enum is the contract; never ship anything else.
    for (const b of buttons) if (!ALLOWED_NAMES.has(b.name)) throw new Error(`زر غير مدعوم: ${b.name}`);

    const caption = `${name}\n\n🧩 الأزرار التفاعلية:\nاختر أمراً من القائمة، أو افتح المستودع، أو انسخ بيانات البوت.`;
    await conn.sendButtonNormal(m.chat, {
      media: mediaFor(images, 0),
      mediaType: 'image',
      caption,
      footer: nonEmpty(info?.nameChannel || name, ''),
      buttons
    }, m);
    return undefined;
  } catch (error) {
    console.error('[native/buttons]', error);
    await say(m, `❌ حدث خطأ أثناء بناء الأزرار: ${(error && error.message) || error}`);
    return undefined;
  }
};

handler.usage = ['اختر', 'ازرار'];
handler.command = ['اختر', 'ازرار', 'buttons'];
handler.category = 'native';

export default handler;